'source-tab':id=>{sourceTab=id;render()},'source-new':()=>editSource(),'source-edit':editSource,'refresh-source':id=>mutate('refresh',{id}),
'source-result':id=>showDetails('Результат импорта',state.config.sources.find(x=>x.id===id)),
'delete-source':async id=>{if(confirm('Удалить подписку и её серверы?')){await mutate('source',{id,delete:true});$('#dialog').close();sourceTab='all';render()}},
'import':()=>modal('Добавить отдельные серверы',area('text','Вставьте ссылки, JSON или Clash YAML',''),async f=>mutate('import',{text:f.get('text')})),
'server-toggle':id=>mutate('server',{id,enabled:!state.config.servers.find(x=>x.id===id).enabled}),
'server-auto':id=>mutate('server',{id,auto:!state.config.servers.find(x=>x.id===id).auto}),
'server-detail':id=>{const s=state.config.servers.find(x=>x.id===id);modal(s.name,`<p>${esc(s.outbound.type)} · ${esc(s.outbound.server)}:${s.outbound.server_port}</p>${checkDetails(state.results[id])}${field('name','Название',s.name)}${field('priority','Приоритет при равном качестве',s.priority,'number')}<div class="actions">${button('Удалить','delete-server',id,'danger small')}</div>`,async f=>mutate('server',{id,name:f.get('name'),priority:Number(f.get('priority'))}))},
'delete-server':async id=>{if(confirm('Удалить сервер? При обновлении подписки он может появиться снова.')){await mutate('server',{id,delete:true});$('#dialog').close();render()}},
'client-new':()=>editClient(),'client-edit':editClient,'disconnect':id=>mutate('disconnect',{id}),
