'rotate':async id=>{if(confirm('Старые пароль и ссылка перестанут работать. Продолжить?')){await mutate('client',{id,rotate:true});$('#dialog').close();render()}},
'reveal':id=>{const input=document.getElementById(id);input.type=input.type==='password'?'text':'password'},
