'client-link':id=>{const u=state.config.clients.find(x=>x.id===id);modal('Подключение: '+u.name,u.tg_url?`<img class="qr" src="api/qr/${id}" alt="QR подключения"><label>Ссылка Telegram</label>${secretField(u.tg_url,'tg-link')}<div class="actions"><a class="button" href="${esc(u.tg_url)}">Открыть Telegram</a></div>`:'<p>Сначала укажите адрес подключения в разделе «Настройка прокси».</p>',null)},
'load-history':async()=>{await loadHistory();render()},
'history-all':async()=>{historyClient='';await loadHistory();render()},
'client-history':async id=>{historyClient=id;if(page!=='history')location.hash='history';else{await loadHistory();render()}},
'job-result':id=>showDetails('Результат',state.jobs.find(x=>x.id===id)?.result),
'cleanup':()=>mutate('cleanup',{}),'clear-history':()=>{if(confirm('Удалить историю соединений и событий? Доступы сохранятся.'))return mutate('cleanup',{clear:true})},
'tg-toggle':()=>mutate('settings',{settings:{telegram_enabled:!state.config.settings.telegram_enabled}}),
'proxy-settings':()=>{const s=state.config.settings;modal('Адрес и порты',field('public_host','Адрес подключения (домен или IP, без протокола)',s.public_host)+field('http_port','Порт HTTP',s.http_port,'number')+field('socks_port','Порт SOCKS5',s.socks_port,'number')+field('telegram_port','Порт MTProxy',s.telegram_port,'number')+field('http_ip_port','Порт HTTP по IP',state.config.access.port,'number')+check('http_ip_enabled','HTTP по IP включён',state.config.access.enabled)+check('http_enabled','HTTP включён',s.http_enabled)+check('socks_enabled','SOCKS5 включён',s.socks_enabled)+check('telegram_enabled','MTProxy включён',s.telegram_enabled)+select('http_auth','Авторизация HTTP',s.http_auth,{password:'Логин и пароль клиента; доверенные адреса по правилам',trusted:'Без пароля только для доверенных адресов'})+select('socks_auth','Авторизация SOCKS5',s.socks_auth,{password:'Логин и пароль клиента; доверенные адреса по правилам',trusted:'Без пароля только для доверенных адресов'})+'<p class="muted">MTProxy всегда требует секрет. Для отдельного порта с одобрением адреса используйте «Доступ по IP».</p>'+field('front_domain','Домен Fake TLS для новых клиентов',s.front_domain),async f=>{const b={};for(const k of ['public_host','front_domain','http_auth','socks_auth'])b[k]=f.get(k);for(const k of ['http_port','socks_port','telegram_port'])b[k]=Number(f.get(k));for(const k of ['http_enabled','socks_enabled','telegram_enabled'])b[k]=f.has(k);await mutate('settings',{settings:b,access:{port:Number(f.get('http_ip_port')),enabled:f.has('http_ip_enabled')}})})},
'routing':()=>{const r=state.config.routing;modal('Маршрутизация',select('mode','Общий режим',r.mode,Object.fromEntries(Object.entries(modes).filter(([k])=>k!=='default')))+area('vpn_domains','Домены через VPN — по одному в строке',r.vpn_domains.join('\n'))+area('direct_domains','Домены напрямую — по одному в строке',r.direct_domains.join('\n'))+area('vpn_ips','IP/CIDR через VPN',r.vpn_ips.join('\n'))+area('direct_ips','IP/CIDR напрямую',r.direct_ips.join('\n'))+area('sources','Обновляемые списки (JSON)',JSON.stringify(r.sources,null,2))+area('presets','Наборы доменов: openai, youtube, discord, telegram, spotify…',r.presets.join('\n')),async f=>{const b={mode:f.get('mode'),sources:JSON.parse(f.get('sources'))};for(const k of ['vpn_domains','direct_domains','vpn_ips','direct_ips','presets'])b[k]=f.get(k).split('\n').map(x=>x.trim()).filter(Boolean);await mutate('settings',{routing:b})})},
'automation':()=>{const s=state.config.settings;const titles={check_interval:'Текущий сервер, секунд',scan_interval:'Пауза между обходами серверов, секунд',availability_interval:'Доступность сайтов, секунд',subscription_interval:'Подписки по умолчанию, секунд',parallel_checks:'Одновременных проверок',switch_margin_ms:'Улучшение задержки для переключения, мс',switch_margin_percent:'Минимальное улучшение задержки, %',check_timeout:'Тайм-аут одного запроса, секунд'};modal('Автоматическая работа',Object.entries(titles).map(([k,t])=>field(k,t,s[k],'number')).join('')+area('foreign_urls','Зарубежные контрольные HTTPS-адреса',s.foreign_urls.join('\n'))+area('russian_urls','Российские контрольные HTTPS-адреса',s.russian_urls.join('\n'))+area('service_urls','Отдельно проверяемые сервисы',s.service_urls.join('\n')),async f=>{const b={};for(const k of Object.keys(titles))b[k]=Number(f.get(k));for(const k of ['foreign_urls','russian_urls','service_urls'])b[k]=f.get(k).split('\n').map(x=>x.trim()).filter(Boolean);await mutate('settings',{settings:b})})},
'retention':()=>{const s=state.config.settings;const titles={history_days:'Хранить дней',history_records:'Максимум соединений в истории',event_records:'Максимум событий',history_mb:'Предел хранилища, МБ'};modal('Хранение данных',Object.entries(titles).map(([k,t])=>field(k,t,s[k],'number')).join(''),async f=>mutate('settings',{settings:Object.fromEntries(Object.keys(titles).map(k=>[k,Number(f.get(k))]))}))},
'security':()=>editSecurity(),
