'remove-trusted':id=>document.getElementById(id)?.remove(),
'route-test':()=>modal('Проверить маршрут',field('host','Домен или IP')+select('client_id','Клиент','',{'':'Общие настройки',...Object.fromEntries(state.config.clients.map(x=>[x.id,x.name]))}),async f=>{const r=await api('route-test',Object.fromEntries(f));notice(`${r.route}: ${r.reason}`)}),
'migration':()=>showDetails('Перенос из 4.x',state.config.migration), 'legacy':()=>showDetails('Исходные дополнительные данные',state.config.legacy),
