document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();b.disabled=true;try{await handlers[b.dataset.action]?.(b.dataset.id)}catch(e){notice(e.message,true)}finally{b.disabled=false}});
document.addEventListener('change',e=>{if(e.target.id==='server-search'){search=e.target.value;render()}if(e.target.id==='server-sort'){sort=e.target.value;render()}});
$('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{if(dialogSubmit)await dialogSubmit(new FormData(e.target));$('#dialog').close();render()}catch(e){notice(e.message,true)}finally{b.disabled=false}});
$('#cancel-dialog').onclick=()=>$('#dialog').close();$('#refresh-view').onclick=refresh;
window.addEventListener('hashchange',async()=>{page=location.hash.slice(1);if(['history','diagnostics'].includes(page))await loadHistory();render()});
async function loadHistory(){historyData=await api('history'+(page==='history'&&historyClient?'?client_id='+encodeURIComponent(historyClient):''))}
refresh();setInterval(refresh,3000);

function checkDetails(h){
 if(!h)return '<p>Сервер ещё не проверен.</p>';
 const names={foreign:'Зарубежные сайты',russian:'Российские сайты',services:'Отдельные сервисы'};
 const status={ok:'Доступ подтверждён',limited:'Автоматическая проверка ограничена',restricted:'Сайт сообщил об ограничении',error:'Ошибка ответа сайта',unreachable:'Соединение не установлено'};
 return Object.entries(names).map(([key,title])=>`<h3>${title}</h3>${(h[key]||[]).map(x=>`<div class="connection"><b>${esc(new URL(x.url).hostname)}</b><p>${esc(status[x.status]||x.status)} ${x.reason?'· '+esc(x.reason):''} ${x.http_status?'· HTTP '+x.http_status:''} ${x.ms!=null?'· '+x.ms+' мс':''}</p></div>`).join('')}`).join('')+`<small>Полная проверка: ${date(h.full_at)}</small><details><summary>Технические данные</summary><pre>${esc(JSON.stringify(h,null,2))}</pre></details>`;
}

let trustedCounter=0;
function trustedRow(x={}){const id='trusted-'+(++trustedCounter);return `<div class="trusted-entry panel" id="${id}"><label>Адрес или сеть CIDR</label><input class="trusted-cidr" value="${esc(x.cidr||'')}" placeholder="192.168.1.20/32"><label>Клиент для учёта подключений</label><select class="trusted-client">${state.config.clients.map(u=>`<option value="${u.id}" ${u.id===x.client_id?'selected':''}>${esc(u.name)}</option>`).join('')}</select><label class="check"><input class="trusted-http" type="checkbox" ${!x.protocols||x.protocols.includes('http')?'checked':''}>HTTP</label><label class="check"><input class="trusted-socks" type="checkbox" ${x.protocols?.includes('socks')?'checked':''}>SOCKS5</label>${button('Удалить правило','remove-trusted',id)}</div>`}
function editSecurity(){const v=state.config.security;modal('Доступ и защита',check('trusted_enabled','Разрешить доверенным адресам доступ без пароля',v.trusted_enabled)+`<p class="muted">Каждый адрес привязан к клиенту для истории и ограничений.</p><div id="trusted-rows">${v.trusted.map(trustedRow).join('')}</div>${button('Добавить доверенный адрес','add-trusted')}`+area('deny_cidrs','Заблокированные IP/CIDR, по одному в строке',v.deny_cidrs.join('\n'))+area('allow_cidrs','Разрешённые IP/CIDR (пусто — без этого ограничения)',v.allow_cidrs.join('\n'))+check('autoban_enabled','Автоматическая защита от частых подключений',v.autoban_enabled)+field('max_per_ip','Максимум соединений с одного IP',v.max_per_ip,'number')+field('new_per_minute','Новых соединений в минуту с одного IP',v.new_per_minute,'number')+field('auth_failures','Ошибок авторизации за минуту до блокировки',v.auth_failures,'number')+field('ban_seconds','Длительность автоблокировки, секунд',v.ban_seconds,'number')+check('country_enabled','Ограничивать доступ сетями из списка страны',v.country_enabled)+field('country_url','Адрес списка сетей страны',v.country_url,'url'),async f=>{const b={country_url:f.get('country_url'),trusted:[...document.querySelectorAll('.trusted-entry')].map(e=>({cidr:e.querySelector('.trusted-cidr').value.trim(),client_id:e.querySelector('.trusted-client').value,protocols:['http','socks'].filter(k=>e.querySelector('.trusted-'+k).checked)}))};for(const k of ['trusted_enabled','autoban_enabled','country_enabled'])b[k]=f.has(k);for(const k of ['max_per_ip','new_per_minute','ban_seconds','auth_failures'])b[k]=Number(f.get(k));for(const k of ['deny_cidrs','allow_cidrs'])b[k]=f.get(k).split('\n').map(x=>x.trim()).filter(Boolean);await mutate('settings',{security:b})})}

function updateAction(){
 if(!manualJob||!state)return;
 const j=state.jobs.find(x=>x.id===manualJob);if(!j)return;
 if(j.state==='running')notice(j.title+': '+(j.title.includes('Проверка')&&state.checks.running?`${state.checks.done} из ${state.checks.total}`:'выполняется…'));
 else {notice(j.state==='done'?(j.summary||j.result?.summary||j.title+': готово'):(j.error||'Операция отменена'),j.state==='error');manualJob=''}
}
function telegramPage(){const t=state.telegram_check||{},m=t.media||{};return `<section class="panel"><h2>Автоматический контроль Telegram</h2><p>${esc(({protocol_ok:'Обмен через MTProxy подтверждён во всех проверяемых дата-центрах',partial:'Часть дата-центров не ответила',unreachable:'Обмен через MTProxy не подтверждён'})[t.status]||'Ожидаем проверку MTProxy')}</p><p>${esc(({media_ok:`Файл получен: ${bytes(m.bytes)} · ${m.kbps} КБ/с · DC ${m.dc}`,slow:`Файл получен медленно: ${m.kbps} КБ/с`,unconfigured:'Контрольный файл не настроен',stalled:'Загрузка контрольного файла зависла или прервалась',limited:'Telegram временно ограничил проверки',configuration_error:m.detail})[m.status]||'Медиа ещё не проверены')}</p><small>Одна загрузка не доказывает доступность всех видео. ${date(t.checked_at)}</small><div class="actions">${button('Настроить проверку медиа','media-settings')}${button('Проверить сейчас','check')}</div></section>${clients(true)}`}
function accessPage(){const a=state.config.access,rows=state.access||[],tabs={lan:'Домашняя сеть',approved:'Разрешённые',pending:'Ожидают',blocked:'Запрещённые / пауза'};const visible=rows.filter(r=>accessTab==='blocked'?['blocked','paused'].includes(r.status):r.status===accessTab);return `<section class="panel"><div class="row between"><div><h2>HTTP без пароля · по одобрению IP</h2>${badge(a.enabled?'Включён · порт '+a.port:'Выключен',a.enabled?'ok':'')}<p>Домашние подсети допускаются автоматически. Внешние адреса — после вашего разрешения. Запрет закрывает действующие соединения.</p></div>${button('Настроить','access-settings','','')}</div><div class="actions">${button('Пригласить','access-invite')}${button('Уведомления Telegram','notification-settings')}</div><small>Несколько устройств могут иметь один внешний IP. Число соединений не равно числу устройств. Новый IP требует нового одобрения.</small></section><div class="tabs">${Object.entries(tabs).map(([k,v])=>button(v+' · '+rows.filter(r=>k==='blocked'?['blocked','paused'].includes(r.status):r.status===k).length,'access-tab',k,k===accessTab?'selected':'quiet')).join('')}</div><div class="grid two">${visible.map(r=>{const connections=state.active.filter(x=>x.client_id===r.id);const usage=state.usage[r.id]||{};return `<section class="panel"><div class="row between"><h2>${esc(r.name)}</h2>${badge(r.expires&&r.expires<Date.now()/1000?'Срок истёк':({lan:'Домашняя сеть',approved:'Разрешён',pending:'Ожидает одобрения',paused:'Приостановлен',blocked:'Запрещён'})[r.status])}</div><b>${esc(r.ip)}</b><p>${connections.length} активных соединений · ${bytes((usage.upload||0)+(usage.download||0)+connections.reduce((v,x)=>v+x.upload+x.download,0))} за месяц</p><small>Первый запрос: ${date(r.first_seen)}<br>Последний: ${date(r.last_seen)}<br>Доступ: ${r.expires?'до '+date(r.expires):'без срока'} · ${esc(modes[r.route_mode])}${r.invited?' · по приглашению':''}</small><div class="actions">${r.status!=='approved'&&r.status!=='lan'?button('Разрешить','access-allow',r.ip):button('Приостановить','access-pause',r.ip)}${button('Запретить','access-block',r.ip)}${button('Настроить','access-edit',r.ip)}${button('История','client-history',r.id)}${button('Отключить сейчас','disconnect',r.id)}</div></section>`}).join('')||'<section class="panel empty">Здесь пока нет адресов</section>'}</div>`}
function protectionPage(){return `<section class="panel"><h2>Защита входящих подключений</h2><p>HTTP, SOCKS5, HTTP по IP и MTProxy: ограничения частоты и числа соединений, временные блокировки. MTProxy проверяет секрет до передачи ядру.</p><div class="actions">${button('Настроить защиту','security','','')}${button('Авторизация и порты','proxy-settings')}</div><small>Лимиты защищают ресурсы приложения. Переполнение внешнего канала DDoS-атакой требует защиты на стороне сети.</small></section><section class="panel"><h2>Временные блокировки</h2>${(state.bans||[]).map(x=>`<div class="connection"><b>${esc(x.ip)}</b> · ${esc(x.reason)} · до ${date(x.until)} ${button('Снять блокировку','unban',x.ip)}</div>`).join('')||'<p>Блокировок нет</p>'}</section>`}
Object.assign(handlers,{
 'access-tab':tab=>{accessTab=tab;render()},
 'access-allow':ip=>modal('Разрешить доступ: '+ip,field('hours','Срок, часов (0 — постоянно)',state.config.access.grant_hours,'number')+'<p>Внешний IP может измениться или перейти другому владельцу. Отзыв разрешения сразу закрывает соединения.</p>',async f=>mutate('access-client',{ip,status:'approved',expires:f.get('hours')===''?r.expires:(Number(f.get('hours'))?Date.now()/1000+Number(f.get('hours'))*3600:0)})),
 'access-pause':ip=>mutate('access-client',{ip,status:'paused'}),
 'access-block':ip=>mutate('access-client',{ip,status:'blocked'}),
 'unban':ip=>mutate('unban',{ip}),
 'access-edit':ip=>{const r=state.access.find(x=>x.ip===ip);modal('Доступ: '+ip,field('name','Имя',r.name)+select('route_mode','Маршрутизация',r.route_mode,modes)+field('hours','Новый срок от сейчас, часов (пусто — сохранить; 0 — без срока)','','number'),async f=>mutate('access-client',{ip,name:f.get('name'),route_mode:f.get('route_mode'),expires:f.get('hours')===''?r.expires:(Number(f.get('hours'))?Date.now()/1000+Number(f.get('hours'))*3600:0)}))},
 'access-invite':()=>modal('Пригласить человека',field('name','Кого приглашаем?')+'<p>Ссылка не разрешает доступ сама. Знакомый открывает её из той же сети, из которой затем подключится к прокси. Вы одобряете запрос в приложении.</p>',async f=>{const r=await api('access-invite',{name:f.get('name')});setTimeout(()=>modal('Приглашение',secretField(r.url,'invite-link')+`<p>Действует до ${date(r.expires)}. Отправьте ссылку знакомому вместе с адресом и портом HTTP-прокси.</p>`,null),0)}),
 'access-settings':()=>{const a=state.config.access;modal('HTTP по IP',check('enabled','Отдельный HTTP-порт включён',a.enabled)+field('port','Порт',a.port,'number')+area('lan_cidrs','Ваши домашние подсети — автоматический доступ',a.lan_cidrs.join('\n'))+'<p>Укажите конкретные подсети роутера. Случайные частные сети не считаются домашними автоматически. Через этот порт закрыт доступ к локальным службам и настройкам роутера.</p>'+select('route_mode','Маршрут по умолчанию',a.route_mode,modes)+check('notify_invited_only','Уведомлять только о запросах по приглашению',a.notify_invited_only)+field('invite_minutes','Приглашение действует, минут',a.invite_minutes,'number')+field('pending_hours','Удалять нерассмотренные запросы через, часов',a.pending_hours,'number')+field('pending_limit','Максимум ожидающих адресов',a.pending_limit,'number')+field('grant_hours','Срок нового разрешения по умолчанию, часов',a.grant_hours,'number'),async f=>mutate('settings',{access:{enabled:f.has('enabled'),port:Number(f.get('port')),lan_cidrs:f.get('lan_cidrs').split('\n').map(x=>x.trim()).filter(Boolean),route_mode:f.get('route_mode'),notify_invited_only:f.has('notify_invited_only'),invite_minutes:Number(f.get('invite_minutes')),pending_hours:Number(f.get('pending_hours')),pending_limit:Number(f.get('pending_limit')),grant_hours:Number(f.get('grant_hours'))}}))},
 'notification-settings':()=>notificationSettings(),
 'notification-test':()=>mutate('notification-test',{}),
 'media-file':()=>mutate('media-file',{}),
 'media-settings':()=>{const t=state.config.telegram_probe;modal('Проверка файлов Telegram',check('enabled','Проверять контрольный файл',t.enabled)+field('api_id','Telegram API ID',t.api_id,'number')+field('api_hash','Telegram API hash',t.api_hash,'password')+field('bot_token','Токен контрольного бота',t.bot_token,'password')+field('file_id','file_id контрольного файла (не меньше 64 КБ)',t.file_id)+field('interval','Интервал загрузки для каждого сервера, секунд',t.interval,'number')+field('sample_kb','Размер проверяемого фрагмента, КБ',t.sample_kb,'number')+field('min_kbps','Минимальная скорость фрагмента, КБ/с',t.min_kbps,'number')+button('Создать контрольный файл по сохранённым настройкам','media-file')+'<p>Используется MTProto, без чтения чата и без получения обновлений бота Home Assistant. Файл и настройки достаточно задать один раз. Проверка расходует указанный объём трафика на каждый сервер.</p>',async f=>mutate('settings',{telegram_probe:{enabled:f.has('enabled'),api_id:Number(f.get('api_id')),api_hash:f.get('api_hash'),bot_token:f.get('bot_token'),file_id:f.get('file_id'),interval:Number(f.get('interval')),sample_kb:Number(f.get('sample_kb')),min_kbps:Number(f.get('min_kbps'))}}))}
});

async function notificationSettings(mode){
 const n=state.config.notifications;mode=mode||n.mode||'ha';let error='';
 if(mode==='ha'){try{haRecipients=await api('ha-recipients')}catch(e){error=e.message}}
 const common=check('enabled','Уведомления включены',n.enabled)+`<div class="tabs">${button('Через Home Assistant','notify-mode','ha',mode==='ha'?'selected':'quiet')}${button('Бот вручную','notify-mode','direct',mode==='direct'?'selected':'quiet')}</div>`;
 let fields='';
 if(mode==='ha')fields=`<p>Выберите одного или нескольких получателей существующих ботов. Токен уже хранится в Home Assistant.</p>${error?`<p class="bad-text">${esc(error)}</p>`:''}`+haRecipients.targets.map(x=>check('target',x.name+(x.available?'':' · недоступен'),n.ha_targets.includes(x.id)).replace('name="target"',`name="ha_target" value="${esc(x.id)}"`)).join('')+(!haRecipients.targets.length?'<p>Получатели не найдены. Проверьте интеграцию Telegram в HA или используйте ручные ID ниже.</p>':'')+`<details ${n.ha_chat_ids.length?'open':''}><summary>Добавить ID чатов вручную через существующего бота HA</summary>`+select('ha_entry_id','Бот Home Assistant',n.ha_entry_id,{'':'Выберите бота',...Object.fromEntries(haRecipients.bots.map(x=>[x.id,x.name]))})+area('ha_chat_ids','ID чатов — по одному в строке',n.ha_chat_ids.join('\n'))+'<small>Чаты должны быть разрешены в интеграции Telegram этого бота.</small></details>';
 else fields='<p>Для независимого подключения. Существующий токен можно найти в переписке с @BotFather; новый бот не обязателен.</p>'+field('token','Токен бота — ключ доступа из BotFather',n.token,'password')+field('chat_id','ID чата получателя',n.chat_id)+field('owner_id','Ваш Telegram ID',n.owner_id)+check('poll_callbacks','Это отдельный бот: принимать кнопки «Разрешить / Запретить»',n.poll_callbacks)+'<small>Для бота, используемого HA, оставьте приём кнопок выключенным.</small>';
 modal('Уведомления Telegram',common+fields+field('app_url','HTTPS-ссылка для открытия приложения',n.app_url)+button('Отправить тест по сохранённым настройкам','notification-test'),async f=>{
  const body={mode,enabled:f.has('enabled'),app_url:f.get('app_url')};
  if(mode==='ha')Object.assign(body,{ha_targets:f.getAll('ha_target'),ha_entry_id:f.get('ha_entry_id'),ha_chat_ids:f.get('ha_chat_ids').split(/\s+/).filter(Boolean)});
  else for(const key of ['token','chat_id','owner_id'])body[key]=f.get(key);
  if(mode==='direct')body.poll_callbacks=f.has('poll_callbacks');
  await mutate('settings',{notifications:body});
 });
}
function profileSettings(key){const p=state.config.profiles[key],service=state.services[key],s=state.config.settings;
 modal(proxyNames[key],check('enabled','Прокси включён',service.enabled)+field('port','Порт',service.port,'number')+(key==='http'||key==='socks'?select('auth','Авторизация',s[key+'_auth'],{password:'Логин и пароль; доверенные адреса по правилам',trusted:'Только доверенные адреса без пароля'}):key==='telegram'?'<p>Каждый клиент подключается со своим секретом MTProxy.</p>':'<p>Домашняя сеть допускается автоматически, внешние IP — после одобрения.</p>')+check('manual_failover','При отказе ручного сервера автоматически выбирать резерв',p.manual_failover)+(key==='telegram'?'':select('route_mode','Маршрут по умолчанию',p.route_mode,modes))+`<details><summary>Требования к выбору сервера</summary>${check('require_russian','Требовать подтверждённую доступность всех российских контрольных сайтов',p.require_russian)}${check('require_services','Требовать подтверждённую доступность всех контрольных сервисов',p.require_services)}<p>Отказ автоматическому запросу не доказывает блокировку. Строгие требования могут исключить все серверы. Telegram отдельно учитывает MTProto и контрольный файл.</p></details>`,async f=>{
  const profile={manual_failover:f.has('manual_failover'),require_russian:f.has('require_russian'),require_services:f.has('require_services')};if(key!=='telegram')profile.route_mode=f.get('route_mode');
  const body={profiles:{[key]:profile}};
  if(key==='http_ip')body.access={enabled:f.has('enabled'),port:Number(f.get('port'))};
  else {body.settings={[key+'_enabled']:f.has('enabled'),[key+'_port']:Number(f.get('port'))};if(key==='http'||key==='socks')body.settings[key+'_auth']=f.get('auth')}
  await mutate('settings',body);
 });
}
const lovelaceCard=`type: entities
title: Proxy от Бориса
show_header_toggle: false
entities:
  - entity: sensor.boris_proxy_status
    name: Состояние
  - entity: sensor.boris_proxy_http
    name: HTTP
  - entity: sensor.boris_proxy_socks
    name: SOCKS5
  - entity: sensor.boris_proxy_telegram
    name: Telegram
  - entity: sensor.boris_proxy_http_ip
    name: HTTP по IP
  - entity: button.boris_proxy_check
    name: Проверить и выбрать
footer:
  type: buttons
  entities:
    - entity: switch.boris_proxy_http
      name: HTTP
    - entity: switch.boris_proxy_socks
      name: SOCKS5
    - entity: switch.boris_proxy_telegram
      name: TG
    - entity: switch.boris_proxy_http_ip
      name: По IP
`;
Object.assign(handlers,{
 'proxy-tab':key=>{proxyTab=key;render()},
 'profile-settings':profileSettings,
 'profile-select':key=>mutate('select',{profile:key,id:document.getElementById('manual-'+key).value}),
 'notify-mode':mode=>notificationSettings(mode),
 'ha-settings':()=>modal('Home Assistant и Lovelace','<p>Состояние, выбранный сервер, резерв, время смены и доступность — в сущностях HA. Отдельные переключатели и выбор сервера для каждого прокси.</p><p>Установщик создаёт только интеграцию boris_proxy и файл локального подключения. После первой установки нужен перезапуск Home Assistant в удобное для вас время, затем добавление интеграции «Proxy от Бориса».</p>'+button('Установить / обновить интеграцию','ha-install')+check('enabled','Разрешить интеграции чтение статусов и управление',state.config.ha.enabled)+`<details><summary>Компактная карточка без HACS</summary><p>После подключения вставьте YAML в ручную карточку Lovelace. Нажатие на строку открывает резерв, задержку, время смены и результаты проверок. При изменённых entity_id выберите свои сущности.</p>${area('card','YAML карточки',lovelaceCard)}<p>Для ручного выбора добавьте в карточку select.boris_proxy_http, select.boris_proxy_socks, select.boris_proxy_telegram или select.boris_proxy_http_ip.</p></details>`,async f=>mutate('settings',{ha:{enabled:f.has('enabled')}})),
 'ha-install':()=>mutate('ha-install',{}),
 'connect-device':()=>modal('Подключить устройство',`<div class="connect-choices">${button('Telegram · ссылка и QR','connect-kind','telegram')}${button('Домашнее устройство · HTTP без пароля','connect-kind','home')}${button('Знакомый · приглашение','connect-kind','friend')}${button('Приложение · логин и пароль','connect-kind','password')}</div>`,null),
 'connect-kind':kind=>{
  if(kind==='friend'){handlers['access-invite']();return}
  if(kind==='home'){modal('Домашнее устройство',`<p>В настройках устройства выберите HTTP-прокси. Адрес — локальный IP сервера Home Assistant (не роутера). Порт: <b>${state.config.access.port}</b>. Логин и пароль не нужны.</p><p>${state.config.access.enabled?'Порт включён':'Сначала включите HTTP по IP'}. Домашние подсети: ${esc(state.config.access.lan_cidrs.join(', ')||'не заданы')}.</p><a href="#access" data-action="close-dialog">Открыть доступ по IP</a>`,null);return}
  modal('Новый клиент',field('name','Имя устройства или человека')+`<p>${kind==='telegram'?'Будет создан персональный секрет и ссылка Telegram.':'Будут созданы персональные логин и пароль для HTTP и SOCKS5.'}</p>`,async f=>{await mutate('client',{name:f.get('name'),http:kind!=='telegram',socks:kind!=='telegram',telegram:kind==='telegram'});const client=state.config.clients.at(-1);setTimeout(()=>kind==='telegram'?handlers['client-link'](client.id):editClient(client.id),0)});
 },
 'close-dialog':()=>$('#dialog').close()
});
